import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"模型层 core","description":"","frontmatter":{},"headers":[],"relativePath":"reference/core.md","filePath":"reference/core.md","lastUpdated":1792528262000}`),a={name:`reference/core.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="模型层-core" tabindex="-1">模型层 core <a class="header-anchor" href="#模型层-core" aria-label="Permalink to “模型层 core”">​</a></h1><p><code>@xihan-print/core</code> 是纯 TypeScript 的模型层：模板类型、校验、编辑操作、元素登记表与分页算法，不依赖 DOM，浏览器、Node.js 与其它 JavaScript 运行环境里都能用。模板类型的字段见<a href="./schema">模板类型</a>，元素属性见<a href="./elements">元素</a>。下表按源码模块列出全部导出。</p><h2 id="全部导出" tabindex="-1">全部导出 <a class="header-anchor" href="#全部导出" aria-label="Permalink to “全部导出”">​</a></h2><h3 id="extensions" tabindex="-1">extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to “extensions”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createPrintModel</code></td><td>函数</td><td>合出打印模型：内置扩展 PRINT_CORE_EXTENSION 在前，extensions 按顺序在后。</td></tr><tr><td><code>PRINT_CORE_EXTENSION</code></td><td>常量</td><td>内置扩展：全部内置元素。</td></tr><tr><td><code>PRINT_CORE_EXTENSION_ID</code></td><td>常量</td><td>内置扩展的 id。</td></tr><tr><td><code>PRINT_EXTENSION_SPACES</code></td><td>常量</td><td>打印各层扩展共用的名字空间：元素类型。</td></tr><tr><td><code>PrintCoreExtension</code></td><td>接口</td><td>打印 core 层的扩展：元素原型、编辑方式与校验规则。</td></tr><tr><td><code>PrintModel</code></td><td>接口</td><td>一组扩展合出的打印模型：元素登记表与编辑方式。</td></tr><tr><td><code>PrintRuleContext</code></td><td>接口</td><td>规则拿到的上下文：合并后的元素登记表。</td></tr></tbody></table><h3 id="factory" tabindex="-1">factory <a class="header-anchor" href="#factory" aria-label="Permalink to “factory”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>collectDocumentIds</code></td><td>函数</td><td>收集文档中已使用的页面与元素标识。</td></tr><tr><td><code>createDocument</code></td><td>函数</td><td>生成当前 schema 版本的文档。</td></tr><tr><td><code>CreateDocumentOptions</code></td><td>接口</td><td>文档创建选项。</td></tr><tr><td><code>createEdges</code></td><td>函数</td><td>生成四边相等或逐边指定的边距。</td></tr><tr><td><code>createPage</code></td><td>函数</td><td>生成页面模板：页眉单页时优先首页变体，页脚单页时优先末页变体，页码接续上一页面模板。</td></tr><tr><td><code>createPageBandSet</code></td><td>函数</td><td>生成只含空 default 带区的页眉或页脚。</td></tr><tr><td><code>CreatePageOptions</code></td><td>接口</td><td>页面模板创建选项。</td></tr><tr><td><code>createPaper</code></td><td>函数</td><td>按预设名生成纸张。</td></tr></tbody></table><h3 id="fields" tabindex="-1">fields <a class="header-anchor" href="#fields" aria-label="Permalink to “fields”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>collectDocumentFields</code></td><td>函数</td><td>列出一份模板引用了哪些数据字段，合成去重的字段树，形状同设计器的 fields。</td></tr><tr><td><code>CollectDocumentFieldsOptions</code></td><td>接口</td><td>collectDocumentFields 的选项。</td></tr></tbody></table><h3 id="geometry" tabindex="-1">geometry <a class="header-anchor" href="#geometry" aria-label="Permalink to “geometry”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>getBandRect</code></td><td>函数</td><td>取页眉或页脚带区在纸张上的矩形。</td></tr><tr><td><code>getBodyRect</code></td><td>函数</td><td>取给定页眉、页脚带区之间的正文区。</td></tr><tr><td><code>getContentRect</code></td><td>函数</td><td>取页边距以内的内容区。</td></tr><tr><td><code>getElementRect</code></td><td>函数</td><td>取元素框。</td></tr><tr><td><code>getPageBand</code></td><td>函数</td><td>取页眉或页脚中指定键的带区。</td></tr><tr><td><code>getPaperSize</code></td><td>函数</td><td>取页面按方向换算后的纸张尺寸。</td></tr><tr><td><code>resolvePageBand</code></td><td>函数</td><td>按输出页位置选出页眉或页脚应使用的带区。</td></tr><tr><td><code>resolvePageBandKey</code></td><td>函数</td><td>按输出页位置选出页眉或页脚应使用的带区键。</td></tr><tr><td><code>SheetPosition</code></td><td>接口</td><td>输出页在所属页面模板中的位置。</td></tr></tbody></table><h3 id="layout-boxes" tabindex="-1">layout/boxes <a class="header-anchor" href="#layout-boxes" aria-label="Permalink to “layout/boxes”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>MIN_SHRINK_FONT_SIZE</code></td><td>常量</td><td>缩小字号以容纳文字时的最小字号，单位 pt。</td></tr><tr><td><code>SHRINK_FONT_STEP</code></td><td>常量</td><td>缩小字号的步长，单位 pt。</td></tr></tbody></table><h3 id="layout-design" tabindex="-1">layout/design <a class="header-anchor" href="#layout-design" aria-label="Permalink to “layout/design”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DESIGN_FILLER_ROWS</code></td><td>常量</td><td>设置了补空行的表格在设计态示意的空行数。</td></tr><tr><td><code>DESIGN_SAMPLE_ROWS</code></td><td>常量</td><td>表格缺省示意的数据行数。</td></tr><tr><td><code>DesignLayout</code></td><td>接口</td><td>设计态排版结果：各区的布局盒按元素层级排列，坐标为设计坐标。</td></tr><tr><td><code>DesignLayoutOptions</code></td><td>接口</td><td>设计态排版的选项：度量器、表达式引擎、格式化器、区域与时区同分页。</td></tr><tr><td><code>layoutDesign</code></td><td>函数</td><td>按设计坐标排出页面模板的每个元素，页眉页脚取 options.bands 指定的变体。</td></tr></tbody></table><h3 id="layout-paginate" tabindex="-1">layout/paginate <a class="header-anchor" href="#layout-paginate" aria-label="Permalink to “layout/paginate”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DEFAULT_MAX_SHEETS</code></td><td>常量</td><td>输出页总数上限的缺省值。</td></tr><tr><td><code>paginate</code></td><td>函数</td><td>按数据排出模板文档的全部输出页，返回每页每个元素的布局盒。</td></tr></tbody></table><h3 id="layout-rich-text" tabindex="-1">layout/rich-text <a class="header-anchor" href="#layout-rich-text" aria-label="Permalink to “layout/rich-text”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>RICH_TEXT_BLOCK_GAP</code></td><td>常量</td><td>顶层块与块之间的段距，基准字号的倍数；列表项之间与列表项里的块之间不留段距。</td></tr><tr><td><code>RICH_TEXT_DIVIDER_WIDTH</code></td><td>常量</td><td>分隔线的线宽，单位 mm。</td></tr><tr><td><code>RICH_TEXT_HEADING_SCALES</code></td><td>常量</td><td>一到三级标题的字号，基准字号的倍数。</td></tr><tr><td><code>RICH_TEXT_LIST_INDENT</code></td><td>常量</td><td>每层列表的缩进，基准字号的倍数。</td></tr><tr><td><code>RICH_TEXT_MARKER_GAP</code></td><td>常量</td><td>项目符号或序号与文字之间的间距，基准字号的倍数。</td></tr><tr><td><code>RICH_TEXT_SCRIPT_SCALE</code></td><td>常量</td><td>上标与下标的字号，所在文字字号的倍数。</td></tr></tbody></table><h3 id="layout-text-measure" tabindex="-1">layout/text-measure <a class="header-anchor" href="#layout-text-measure" aria-label="Permalink to “layout/text-measure”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>DEFAULT_FONT_FAMILY</code></td><td>常量</td><td>文字样式没写字体时，量字与渲染共用的字体族。</td></tr></tbody></table><h3 id="layout-types" tabindex="-1">layout/types <a class="header-anchor" href="#layout-types" aria-label="Permalink to “layout/types”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>BarCodeLayoutBox</code></td><td>接口</td><td>一维条码布局盒。</td></tr><tr><td><code>EllipseLayoutBox</code></td><td>接口</td><td>椭圆布局盒。</td></tr><tr><td><code>ExtensionLayoutBox</code></td><td>接口</td><td>扩展元素的布局盒，交给运行时层同一类型的渲染；类型没登记时 data 为 null。</td></tr><tr><td><code>ImageLayoutBox</code></td><td>接口</td><td>图片布局盒。</td></tr><tr><td><code>LayoutBand</code></td><td>接口</td><td>输出页选中的页眉或页脚带区。</td></tr><tr><td><code>LayoutBox</code></td><td>类型</td><td></td></tr><tr><td><code>LayoutBoxBase</code></td><td>接口</td><td>布局盒共有的字段。</td></tr><tr><td><code>LayoutFragment</code></td><td>接口</td><td>跨页续排元素的分段位置。</td></tr><tr><td><code>LayoutSheet</code></td><td>接口</td><td>一张输出页。</td></tr><tr><td><code>LayoutWatermark</code></td><td>类型</td><td>已替换占位的水印。</td></tr><tr><td><code>LineLayoutBox</code></td><td>接口</td><td>直线布局盒。</td></tr><tr><td><code>MatrixCodeLayoutBox</code></td><td>接口</td><td>二维码布局盒。</td></tr><tr><td><code>PaginateOptions</code></td><td>接口</td><td>分页选项。</td></tr><tr><td><code>PAGINATION_DIAGNOSTIC_SEVERITIES</code></td><td>常量</td><td>全部分页诊断码及其固定的严重程度：error 为按模板该画的内容没有画出或输出页被截断，warning 为内容画出了但与设计有出入。</td></tr><tr><td><code>PaginationDiagnostic</code></td><td>类型</td><td>分页诊断：与校验问题同形的 @xihan-ui/designer-kit/schema 的 SchemaIssue，不含文案，严重程度与 target 总是给出。</td></tr><tr><td><code>PaginationDiagnosticCode</code></td><td>类型</td><td>分页诊断码。</td></tr><tr><td><code>PaginationDiagnosticTarget</code></td><td>接口</td><td>分页诊断所在的页面（kind 为 page）或元素（kind 为 element）。</td></tr><tr><td><code>PaginationResult</code></td><td>接口</td><td>分页结果。</td></tr><tr><td><code>PaginationStep</code></td><td>类型</td><td>分页的一步，按发生的先后交给 PaginateOptions.trace。</td></tr><tr><td><code>PrintLayoutError</code></td><td>类</td><td>分页无法进行时抛出的错误。</td></tr><tr><td><code>PrintLayoutErrorCode</code></td><td>类型</td><td>分页无法进行的原因：文档有 error 级校验问题、选项不合法、测量器或格式化器返回了不合法的结果。</td></tr><tr><td><code>RectLayoutBox</code></td><td>接口</td><td>矩形布局盒。</td></tr><tr><td><code>RichTextLayoutBox</code></td><td>接口</td><td>富文本布局盒，跨页时每页一段。</td></tr><tr><td><code>RichTextLine</code></td><td>接口</td><td>富文本排出的一行，长度单位 mm。</td></tr><tr><td><code>RichTextMarker</code></td><td>接口</td><td>列表项的项目符号或序号。</td></tr><tr><td><code>RichTextSpan</code></td><td>接口</td><td>富文本一行里同一样式的一截文字：字号与字间距单位 pt。</td></tr><tr><td><code>TableCellLayout</code></td><td>接口</td><td>表格单元格布局，坐标相对纸张左上角。</td></tr><tr><td><code>TableLayoutBox</code></td><td>接口</td><td>表格布局盒，跨页时每页一段。</td></tr><tr><td><code>TableRowLayout</code></td><td>接口</td><td>表格行布局：表头、数据行、补空行或表尾行。</td></tr><tr><td><code>TextLayoutBox</code></td><td>接口</td><td>文本、长文本与页码的布局盒。</td></tr><tr><td><code>TextMeasurement</code></td><td>接口</td><td>按文本样式排出的文字，长度单位 mm。</td></tr></tbody></table><h3 id="operations-apply" tabindex="-1">operations/apply <a class="header-anchor" href="#operations-apply" aria-label="Permalink to “operations/apply”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>applyOperation</code></td><td>函数</td><td>以纯函数方式执行编辑操作：不修改传入的文档，返回新文档与逆操作数组。</td></tr><tr><td><code>ApplyOperationOptions</code></td><td>接口</td><td>操作选项。</td></tr><tr><td><code>applyOperations</code></td><td>函数</td><td>按顺序执行一组编辑操作，整体成功或整体失败（@xihan-ui/designer-kit 的 applyInSequence）。</td></tr></tbody></table><h3 id="operations-errors" tabindex="-1">operations/errors <a class="header-anchor" href="#operations-errors" aria-label="Permalink to “operations/errors”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>PrintOperationError</code></td><td>类</td><td>操作无法执行时抛出的错误，<code>code</code> 与 <code>params</code> 供调用方判断与生成文案。</td></tr><tr><td><code>PrintOperationErrorCode</code></td><td>类型</td><td>操作无法执行的原因。</td></tr></tbody></table><h3 id="operations-table-plans" tabindex="-1">operations/table-plans <a class="header-anchor" href="#operations-table-plans" aria-label="Permalink to “operations/table-plans”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>MIN_TABLE_COLUMN_WIDTH</code></td><td>常量</td><td>调整列宽时每列的最小宽度，单位 mm。</td></tr><tr><td><code>planInsertFooterRow</code></td><td>函数</td><td>在第 index 个表尾行之前插入一行（index 等于行数时追加）。</td></tr><tr><td><code>planInsertTableColumn</code></td><td>函数</td><td>在第 index 列之前插入一列（index 等于列数时追加在末尾）；跨过插入位置的表尾单元格多跨一列，其余表尾行在新列处留空。</td></tr><tr><td><code>planMergeFooterCells</code></td><td>函数</td><td>合并表尾行里 columnIds 覆盖的列范围：与范围相交的单元格（含留空的列）合成一个，合并后的范围扩到它们的并集；保留最左边那个单元格的内容，最左边是留空的列时新建空白单元格。</td></tr><tr><td><code>planMoveTableColumn</code></td><td>函数</td><td>把一列移到第 index 位（按移动后的顺序数）。</td></tr><tr><td><code>planRemoveFooterRow</code></td><td>函数</td><td>删除一个表尾行。</td></tr><tr><td><code>planRemoveTableColumn</code></td><td>函数</td><td>删除一列：只占这一列的表尾单元格删除，跨过它的缩短一列，从它起跨的改由下一列起跨。</td></tr><tr><td><code>planResizeTableColumn</code></td><td>函数</td><td>把一列调到 width 宽，不小于 MIN_TABLE_COLUMN_WIDTH。</td></tr><tr><td><code>planSplitFooterCell</code></td><td>函数</td><td>把表尾行里从 columnId 起跨的单元格拆成只占一列，空出来的列留空。</td></tr><tr><td><code>TableColumnFit</code></td><td>类型</td><td>列宽怎样跟着变：keep 保持表格宽度、各列按比例缩放；resize 改变表格宽度、其余列不动。</td></tr><tr><td><code>TablePlanRefusal</code></td><td>类型</td><td>计划不能执行的原因：只剩一列、移动会拆开跨列的表尾单元格、所选范围只有一个单元格、单元格本来就不跨列。</td></tr><tr><td><code>TablePlanResult</code></td><td>类型</td><td>计划结果：成功时给出 updateElement 的属性修改。</td></tr></tbody></table><h3 id="operations-types" tabindex="-1">operations/types <a class="header-anchor" href="#operations-types" aria-label="Permalink to “operations/types”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>AddBandOperation</code></td><td>接口</td><td>为页眉或页脚添加变体带区。</td></tr><tr><td><code>AddElementOperation</code></td><td>接口</td><td>向容器添加元素，<code>index</code> 缺省时放在最上层。</td></tr><tr><td><code>AddPageOperation</code></td><td>接口</td><td>添加页面模板，<code>index</code> 缺省时放在末尾。</td></tr><tr><td><code>MoveElementsOperation</code></td><td>接口</td><td>平移一组元素，单位 mm。</td></tr><tr><td><code>MovePageOperation</code></td><td>接口</td><td>移动页面模板到目标下标。</td></tr><tr><td><code>OperationResult</code></td><td>类型</td><td>操作结果，即 @xihan-ui/designer-kit 的 OperationResult：新文档，以及按顺序作用于新文档即可还原出传入文档的逆操作。</td></tr><tr><td><code>PrintOperation</code></td><td>类型</td><td>编辑操作。</td></tr><tr><td><code>PrintOperationType</code></td><td>类型</td><td>编辑操作的种类。</td></tr><tr><td><code>PropertyChange</code></td><td>接口</td><td>一处属性修改。</td></tr><tr><td><code>RemoveBandOperation</code></td><td>接口</td><td>删除页眉或页脚的变体带区及其中的元素。</td></tr><tr><td><code>RemoveElementOperation</code></td><td>接口</td><td>删除元素。</td></tr><tr><td><code>RemovePageOperation</code></td><td>接口</td><td>删除页面模板。</td></tr><tr><td><code>ReorderElementOperation</code></td><td>接口</td><td>调整元素在容器内的层级。</td></tr><tr><td><code>ReorderTarget</code></td><td>类型</td><td>层级调整目标：最上层、最下层、上移一层、下移一层，或容器内的目标下标。</td></tr><tr><td><code>ReplaceDocumentOperation</code></td><td>接口</td><td>整份换成另一份文档，如在 JSON 编辑框里改完应用；新文档由调用方先校验（validateDocument），操作只记下换之前的那份作逆操作。</td></tr><tr><td><code>ResizeElementOperation</code></td><td>接口</td><td>把元素缩放到新的元素框，元素原型可附带专属缩放行为。</td></tr><tr><td><code>UpdateDocumentOperation</code></td><td>接口</td><td>修改文档属性；不能修改 <code>schemaVersion</code> 与 <code>pages</code>。</td></tr><tr><td><code>UpdateElementOperation</code></td><td>接口</td><td>修改元素属性；不能修改 <code>id</code> 与 <code>type</code>。</td></tr><tr><td><code>UpdatePageOperation</code></td><td>接口</td><td>修改页面设置：名称、纸张、方向、边距、页码规则、水印、参考线、宿主附加数据，以及页眉页脚的 <code>singleSheet</code> 和已有带区的 <code>height</code>。</td></tr></tbody></table><h3 id="registry-builtins" tabindex="-1">registry/builtins <a class="header-anchor" href="#registry-builtins" aria-label="Permalink to “registry/builtins”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createBuiltinElementPrototypes</code></td><td>函数</td><td>生成全部内置元素原型，每次调用返回互不共享的新对象。</td></tr><tr><td><code>scaleTableColumns</code></td><td>函数</td><td>按新的总宽度等比缩放列宽，末列吸收舍入误差；原列宽合计不为正时均分。</td></tr></tbody></table><h3 id="registry-part-properties" tabindex="-1">registry/part-properties <a class="header-anchor" href="#registry-part-properties" aria-label="Permalink to “registry/part-properties”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>pageProperties</code></td><td>函数</td><td>页面设置的属性描述，路径相对页面模板；页眉页脚各变体的高度只在该变体存在时显示。</td></tr><tr><td><code>tableBodyProperties</code></td><td>函数</td><td>表体的属性描述，路径相对表体。</td></tr><tr><td><code>tableColumnProperties</code></td><td>函数</td><td>表格列的属性描述，路径相对列；条码码制只在单元格类型为条码时显示。</td></tr><tr><td><code>tableFooterCellProperties</code></td><td>函数</td><td>表尾单元格的属性描述，路径相对单元格。</td></tr><tr><td><code>tableFooterRowProperties</code></td><td>函数</td><td>表尾行的属性描述，路径相对表尾行；单元格另按表尾格编辑。</td></tr><tr><td><code>tableHeaderProperties</code></td><td>函数</td><td>表头的属性描述，路径相对表头；表头隐藏时只显示「是否显示」。</td></tr></tbody></table><h3 id="registry-properties" tabindex="-1">registry/properties <a class="header-anchor" href="#registry-properties" aria-label="Permalink to “registry/properties”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>behaviorProperties</code></td><td>函数</td><td>名称、锁定与只预览不打印。</td></tr><tr><td><code>boxProperties</code></td><td>函数</td><td><code>box</code> 下的背景、边框与内边距。</td></tr><tr><td><code>choices</code></td><td>函数</td><td>一组取值写成 select 编辑方式的选项。</td></tr><tr><td><code>layoutProperties</code></td><td>函数</td><td>坐标、宽高与可选的旋转角度。</td></tr><tr><td><code>property</code></td><td>函数</td><td>生成一条属性描述，缺省为元素上必须有的属性。</td></tr><tr><td><code>PropertyOptions</code></td><td>接口</td><td>属性描述的可选项。</td></tr><tr><td><code>textStyleProperties</code></td><td>函数</td><td><code>style</code> 下的文本样式。</td></tr></tbody></table><h3 id="registry-registry" tabindex="-1">registry/registry <a class="header-anchor" href="#registry-registry" aria-label="Permalink to “registry/registry”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>CreateElementInit</code></td><td>接口</td><td>创建元素的参数。</td></tr><tr><td><code>createElementRegistry</code></td><td>函数</td><td>创建元素类型登记表，默认登记全部内置元素；类型重复时抛出错误。</td></tr><tr><td><code>ElementCategoryGroup</code></td><td>接口</td><td>物料面板中的一个分组。</td></tr><tr><td><code>ElementRegistry</code></td><td>接口</td><td>元素类型登记表。</td></tr></tbody></table><h3 id="registry-types" tabindex="-1">registry/types <a class="header-anchor" href="#registry-types" aria-label="Permalink to “registry/types”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>AnyElementPrototype</code></td><td>类型</td><td>任一元素的原型：内置元素的，或扩展元素的。</td></tr><tr><td><code>ELEMENT_CATEGORIES</code></td><td>常量</td><td>内置的物料分组，按面板中的显示顺序；扩展自定的分组排在它们之后。</td></tr><tr><td><code>ElementCategory</code></td><td>类型</td><td>内置的物料分组：文字、图片、数据、图形、条码。</td></tr><tr><td><code>ElementDefaults</code></td><td>类型</td><td>元素默认值：不含标识与坐标。</td></tr><tr><td><code>ElementFieldReference</code></td><td>接口</td><td>元素引用的一个数据字段。</td></tr><tr><td><code>ElementFieldsContext</code></td><td>接口</td><td>列字段引用时拿到的帮手：把常见的内容来源换成引用，扩展元素不必自己解析模板串与表达式。</td></tr><tr><td><code>ElementFlowContext</code></td><td>接口</td><td>跨页扩展元素取值时拿到的上下文：在排版上下文之上还能量文字。</td></tr><tr><td><code>ElementLayoutContext</code></td><td>接口</td><td>扩展元素排版时拿到的上下文。</td></tr><tr><td><code>ElementPrototype</code></td><td>接口</td><td>元素原型：一种元素的默认值、尺寸约束、可编辑属性与专属行为。</td></tr><tr><td><code>ElementValidationContext</code></td><td>接口</td><td>元素专属规则的校验上下文。</td></tr><tr><td><code>ExtensionElementPrototype</code></td><td>类型</td><td>扩展元素的原型：不跨页的给 layout，跨页的给 prepare。</td></tr><tr><td><code>ExtensionFlowBlock</code></td><td>接口</td><td>跨页扩展元素的一块：块不拆开，height 是它占的高度（mm），data 交给渲染，要是 JSON。</td></tr><tr><td><code>ExtensionFlowContent</code></td><td>接口</td><td>跨页扩展元素排出的内容：blocks 依次排；repeat 给了时排在每一段的开头（如表头），算进每段的高度。</td></tr><tr><td><code>FixedExtensionElementPrototype</code></td><td>接口</td><td>不跨页的扩展元素的原型：必须给出 layout。</td></tr><tr><td><code>FlowExtensionElementPrototype</code></td><td>接口</td><td>跨页的扩展元素的原型：必须给出 prepare；只能放在正文区。</td></tr><tr><td><code>NumberControl</code></td><td>类型</td><td>数值属性：designer-kit 的 number 编辑方式，单位取打印的单位。</td></tr><tr><td><code>PAGE_PROPERTY_GROUPS</code></td><td>常量</td><td>页面设置的属性分组取值，按面板中的显示顺序。</td></tr><tr><td><code>PROPERTY_GROUPS</code></td><td>常量</td><td>元素与表格部位的属性分组取值，按面板中的显示顺序。</td></tr><tr><td><code>PropertyControl</code></td><td>类型</td><td>属性编辑方式：@xihan-ui/designer-kit/properties 的内建编辑方式（数值的单位取打印的单位），加上打印专属的复合类型；复合类型由设计器提供对应的专用编辑器。</td></tr><tr><td><code>PropertyControlKind</code></td><td>类型</td><td>属性编辑方式的种类。</td></tr><tr><td><code>PropertyDescriptor</code></td><td>接口</td><td>可编辑属性描述：@xihan-ui/designer-kit/properties 的 PropertyDescriptor，path 相对元素；分组总是给出，显示条件写在 visibleWhen；required（显示时必须填写）不用，空值由打印自己的规则报告。</td></tr><tr><td><code>PropertyGroup</code></td><td>类型</td><td>属性面板分组：元素与表格部位用布局、内容、数据、文字、表格、条码、外观、行为，页面设置用页面、纸张、页眉页脚、页码、水印。</td></tr><tr><td><code>PropertyUnit</code></td><td>类型</td><td>数值属性的单位：mm、pt、角度、倍数或个数。</td></tr><tr><td><code>SidesControl</code></td><td>类型</td><td>四边距离：designer-kit 的 sides 编辑方式，单位取打印的单位。</td></tr></tbody></table><h3 id="schema-common" tabindex="-1">schema/common <a class="header-anchor" href="#schema-common" aria-label="Permalink to “schema/common”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>BorderSides</code></td><td>接口</td><td>四边边框，缺省的一边不画线。</td></tr><tr><td><code>BoxStyle</code></td><td>接口</td><td>元素外框样式。</td></tr><tr><td><code>Color</code></td><td>类型</td><td>颜色：<code>#RGB</code>、<code>#RGBA</code>、<code>#RRGGBB</code>、<code>#RRGGBBAA</code> 或 <code>transparent</code>。</td></tr><tr><td><code>Edges</code></td><td>接口</td><td>四边距离，单位 mm。</td></tr><tr><td><code>ExpressionFormat</code></td><td>接口</td><td>表达式格式：以受限表达式把值转成显示文本，表达式中以 <code>value</code> 引用待格式化的值。</td></tr><tr><td><code>ExpressionTextContent</code></td><td>接口</td><td>以受限表达式计算的文本，表达式中的变量为数据对象的顶层字段。</td></tr><tr><td><code>FieldImageSource</code></td><td>接口</td><td>从数据字段读取图片地址。</td></tr><tr><td><code>FieldTextContent</code></td><td>接口</td><td>绑定单个数据字段。</td></tr><tr><td><code>ImageSource</code></td><td>类型</td><td>图片来源。</td></tr><tr><td><code>MapFormat</code></td><td>接口</td><td>值映射格式：按数据值查表显示文本。</td></tr><tr><td><code>StaticImageSource</code></td><td>接口</td><td>固定地址的图片。</td></tr><tr><td><code>StaticTextContent</code></td><td>接口</td><td>固定文本。</td></tr><tr><td><code>Stroke</code></td><td>接口</td><td>描边。</td></tr><tr><td><code>TemplateTextContent</code></td><td>接口</td><td>含 <code>{{path}}</code> 占位的文本模板，占位按数据字段替换。</td></tr><tr><td><code>TextContent</code></td><td>类型</td><td>文本内容来源。</td></tr><tr><td><code>TextStyle</code></td><td>接口</td><td>文本样式。</td></tr><tr><td><code>ValueFormat</code></td><td>类型</td><td>值格式：数字、百分比、日期与人民币大写即 @xihan-ui/expression 的 FormatSpec，交给注入的格式化器；值映射在本包内完成，表达式格式经表达式接入点。</td></tr><tr><td><code>ValueMapEntry</code></td><td>接口</td><td>值映射的一项：数据值（按字符串比较）与显示文本，与选择类组件的选项同一形状（不带 disabled）。</td></tr></tbody></table><h3 id="schema-document" tabindex="-1">schema/document <a class="header-anchor" href="#schema-document" aria-label="Permalink to “schema/document”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>PageBand</code></td><td>接口</td><td>页眉或页脚的一个带区。</td></tr><tr><td><code>PageBandSet</code></td><td>接口</td><td>页眉或页脚：<code>default</code> 为常规带区，其余为按输出页命中的变体。</td></tr><tr><td><code>PageGuides</code></td><td>接口</td><td>参考线：设计时对位用，不参与分页也不打印；坐标相对纸张左上角（按页面方向换算后的纸张），单位 mm。</td></tr><tr><td><code>PageNumbering</code></td><td>接口</td><td>页码编号规则。</td></tr><tr><td><code>PaperSpec</code></td><td>接口</td><td>纸张。</td></tr><tr><td><code>PRINT_SCHEMA_VERSION</code></td><td>常量</td><td>当前模板 schema 版本。</td></tr><tr><td><code>PrintDocument</code></td><td>接口</td><td>打印模板文档。</td></tr><tr><td><code>PrintPage</code></td><td>接口</td><td>页面模板：一份页面模板按数据量排出一张或多张输出页。</td></tr><tr><td><code>PrintSchemaVersion</code></td><td>类型</td><td>模板 schema 版本号类型。</td></tr><tr><td><code>Watermark</code></td><td>接口</td><td>平铺文字水印。</td></tr></tbody></table><h3 id="schema-elements" tabindex="-1">schema/elements <a class="header-anchor" href="#schema-elements" aria-label="Permalink to “schema/elements”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>BarCodeElement</code></td><td>接口</td><td>一维条码。</td></tr><tr><td><code>BarCodeTextStyle</code></td><td>接口</td><td>条码下方文字的样式。</td></tr><tr><td><code>ElementBase</code></td><td>接口</td><td>全部元素共有的字段。</td></tr><tr><td><code>EllipseElement</code></td><td>接口</td><td>椭圆，内切于元素框。</td></tr><tr><td><code>ExtensionElement</code></td><td>接口</td><td>扩展登记的元素：通用字段之外的属性由扩展的原型定义，取值都是 JSON。</td></tr><tr><td><code>ImageElement</code></td><td>接口</td><td>图片。</td></tr><tr><td><code>LineElement</code></td><td>接口</td><td>直线，走向由元素框和方向共同决定。</td></tr><tr><td><code>LongTextElement</code></td><td>接口</td><td>随内容纵向延展并可跨页续排的长文本。</td></tr><tr><td><code>MatrixCodeElement</code></td><td>接口</td><td>二维码：QR、Data Matrix、PDF417、Aztec。</td></tr><tr><td><code>PageNumberElement</code></td><td>接口</td><td>页码。</td></tr><tr><td><code>PRINT_ELEMENT_TYPES</code></td><td>常量</td><td>内置元素类型列表。</td></tr><tr><td><code>PrintElement</code></td><td>类型</td><td>内置元素。</td></tr><tr><td><code>PrintElementOf</code></td><td>类型</td><td>按类型取元素接口。</td></tr><tr><td><code>PrintElementType</code></td><td>类型</td><td>内置元素类型。</td></tr><tr><td><code>RectElement</code></td><td>接口</td><td>矩形。</td></tr><tr><td><code>RichTextContent</code></td><td>类型</td><td>富文本的内容来源：模板里写死的文档，或从数据字段读取。</td></tr><tr><td><code>RichTextElement</code></td><td>接口</td><td>随内容纵向延展并可跨页续排的富文本：段落、标题、列表、分隔线与带样式的文字。</td></tr><tr><td><code>TableElement</code></td><td>接口</td><td>绑定数组数据、随行数延展并可跨页续排的表格。</td></tr><tr><td><code>TextElement</code></td><td>接口</td><td>固定尺寸的文本。</td></tr></tbody></table><h3 id="schema-options" tabindex="-1">schema/options <a class="header-anchor" href="#schema-options" aria-label="Permalink to “schema/options”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>AGGREGATE_FUNCTIONS</code></td><td>常量</td><td>表格汇总函数取值。</td></tr><tr><td><code>AGGREGATE_SCOPES</code></td><td>常量</td><td>表格汇总范围取值。</td></tr><tr><td><code>AggregateFunction</code></td><td>类型</td><td>表格汇总函数。</td></tr><tr><td><code>AggregateScope</code></td><td>类型</td><td>表格汇总范围：page 本页数据，cumulative 截至本页的累计数据，all 全部数据。</td></tr><tr><td><code>BarCodeFormat</code></td><td>类型</td><td>转导出自 @xihan-ui/headless</td></tr><tr><td><code>HORIZONTAL_ALIGNS</code></td><td>常量</td><td>单元格水平对齐取值。</td></tr><tr><td><code>HorizontalAlign</code></td><td>类型</td><td>单元格水平对齐。</td></tr><tr><td><code>IMAGE_FITS</code></td><td>常量</td><td>图片适配方式取值。</td></tr><tr><td><code>ImageFit</code></td><td>类型</td><td>图片在元素框内的适配方式。</td></tr><tr><td><code>LINE_DIRECTIONS</code></td><td>常量</td><td>直线方向取值。</td></tr><tr><td><code>LineDirection</code></td><td>类型</td><td>直线在元素框内的走向：horizontal 沿垂直中线，vertical 沿水平中线，diagonalDown 左上到右下，diagonalUp 左下到右上。</td></tr><tr><td><code>MatrixCodeFormat</code></td><td>类型</td><td>转导出自 @xihan-ui/headless</td></tr><tr><td><code>MatrixCodeLevel</code></td><td>类型</td><td>转导出自 @xihan-ui/headless</td></tr><tr><td><code>PAGE_BAND_VARIANTS</code></td><td>常量</td><td>页眉页脚的页面变体键。</td></tr><tr><td><code>PAGE_ORIENTATIONS</code></td><td>常量</td><td>页面方向取值。</td></tr><tr><td><code>PageBandKey</code></td><td>类型</td><td>页眉页脚的全部带区键，<code>default</code> 为未命中任何变体时使用的带区。</td></tr><tr><td><code>PageBandVariant</code></td><td>类型</td><td>页眉页脚变体：first 首页、last 末页、odd 奇数页、even 偶数页（按页码奇偶）。</td></tr><tr><td><code>PageOrientation</code></td><td>类型</td><td>页面方向：portrait 纵向，landscape 横向（宽高互换）。</td></tr><tr><td><code>RICH_TEXT_SOURCES</code></td><td>常量</td><td>富文本字段的内容格式取值。</td></tr><tr><td><code>RichTextSource</code></td><td>类型</td><td>富文本字段的内容格式：html 为 HTML 串，按白名单换成文档；document 为富文本文档对象。</td></tr><tr><td><code>SINGLE_SHEET_PREFERENCES</code></td><td>常量</td><td>同一输出页既是首页又是末页时优先采用的变体取值。</td></tr><tr><td><code>SingleSheetPreference</code></td><td>类型</td><td>同一输出页既是首页又是末页时优先采用的变体。</td></tr><tr><td><code>STROKE_STYLES</code></td><td>常量</td><td>线型取值。</td></tr><tr><td><code>StrokeStyle</code></td><td>类型</td><td>线型。</td></tr><tr><td><code>TABLE_CELL_TYPES</code></td><td>常量</td><td>表格列单元格的呈现类型取值。</td></tr><tr><td><code>TABLE_FOOTER_PLACEMENTS</code></td><td>常量</td><td>表尾行出现位置取值。</td></tr><tr><td><code>TABLE_ROW_HEIGHT_MODES</code></td><td>常量</td><td>表体行高模式取值。</td></tr><tr><td><code>TableCellType</code></td><td>类型</td><td>表格列单元格的呈现类型。</td></tr><tr><td><code>TableFooterPlacement</code></td><td>类型</td><td>表尾行出现位置：everyPage 表格所跨的每一页，lastPage 仅表格结束的那一页。</td></tr><tr><td><code>TableRowHeightMode</code></td><td>类型</td><td>表体行高模式：fixed 每行固定为设定的行高，minimum 以设定的行高为下限、按单元格内容撑高。</td></tr><tr><td><code>TEXT_ALIGNS</code></td><td>常量</td><td>文本水平对齐取值。</td></tr><tr><td><code>TEXT_OVERFLOWS</code></td><td>常量</td><td>固定尺寸文本的溢出处理取值。</td></tr><tr><td><code>TextAlign</code></td><td>类型</td><td>文本水平对齐。</td></tr><tr><td><code>TextOverflow</code></td><td>类型</td><td>固定尺寸文本的溢出处理：clip 裁切，shrink 缩小字号以容纳，visible 允许溢出显示。</td></tr><tr><td><code>VERTICAL_ALIGNS</code></td><td>常量</td><td>垂直对齐取值。</td></tr><tr><td><code>VerticalAlign</code></td><td>类型</td><td>垂直对齐。</td></tr></tbody></table><h3 id="schema-table" tabindex="-1">schema/table <a class="header-anchor" href="#schema-table" aria-label="Permalink to “schema/table”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>AggregateCellContent</code></td><td>接口</td><td>表尾单元格的汇总内容。</td></tr><tr><td><code>CellStyle</code></td><td>接口</td><td>单元格样式。</td></tr><tr><td><code>TableBody</code></td><td>接口</td><td>表体。</td></tr><tr><td><code>TableBorder</code></td><td>接口</td><td>表格网格线。</td></tr><tr><td><code>TableCellContent</code></td><td>类型</td><td>表体单元格内容来源。</td></tr><tr><td><code>TableColumn</code></td><td>接口</td><td>表格列。</td></tr><tr><td><code>TableExpressionCellContent</code></td><td>接口</td><td>表体单元格以受限表达式计算，表达式中的变量为行对象的顶层字段。</td></tr><tr><td><code>TableFieldCellContent</code></td><td>接口</td><td>表体单元格显示行内字段。</td></tr><tr><td><code>TableFooterCell</code></td><td>接口</td><td>表尾单元格。</td></tr><tr><td><code>TableFooterCellContent</code></td><td>类型</td><td>表尾单元格内容：固定文本、根数据字段、根数据模板或汇总值。</td></tr><tr><td><code>TableFooterRow</code></td><td>接口</td><td>表尾行，可承载固定文字、根数据字段与汇总值。</td></tr><tr><td><code>TableHeader</code></td><td>接口</td><td>表头。</td></tr><tr><td><code>TableRowNumberCellContent</code></td><td>接口</td><td>表体单元格显示从 1 开始、跨页连续的行序号。</td></tr><tr><td><code>TableTemplateCellContent</code></td><td>接口</td><td>表体单元格按行对象替换 <code>{{path}}</code> 占位。</td></tr></tbody></table><h3 id="traverse" tabindex="-1">traverse <a class="header-anchor" href="#traverse" aria-label="Permalink to “traverse”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ElementContainerRef</code></td><td>类型</td><td>元素容器：页面正文，或页眉、页脚中的某个带区。</td></tr><tr><td><code>ElementLocation</code></td><td>接口</td><td>元素在文档中的位置。</td></tr><tr><td><code>ElementRegion</code></td><td>类型</td><td>元素所在区域：正文、页眉或页脚。</td></tr><tr><td><code>findElement</code></td><td>函数</td><td>按标识查找元素。</td></tr><tr><td><code>findPage</code></td><td>函数</td><td>按标识查找页面及其下标。</td></tr><tr><td><code>forEachElement</code></td><td>函数</td><td>按页面、正文、页眉、页脚的顺序遍历全部元素。</td></tr><tr><td><code>getContainerElements</code></td><td>函数</td><td>取容器的元素数组；页面或带区不存在时返回 undefined。</td></tr><tr><td><code>getContainerPath</code></td><td>函数</td><td>取容器元素数组相对页面的 JSON 路径。</td></tr><tr><td><code>listContainers</code></td><td>函数</td><td>列出页面上的全部容器，按正文、页眉、页脚的顺序。</td></tr><tr><td><code>listPageBandKeys</code></td><td>函数</td><td>列出页眉或页脚中已存在的带区键。</td></tr><tr><td><code>PAGE_BAND_KEYS</code></td><td>常量</td><td>页眉页脚带区键，按 default、first、last、odd、even 的顺序。</td></tr></tbody></table><h3 id="validation-checks" tabindex="-1">validation/checks <a class="header-anchor" href="#validation-checks" aria-label="Permalink to “validation/checks”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>isValidColor</code></td><td>函数</td><td>判断颜色是否为 <code>transparent</code> 或以 <code>#</code> 开头的 3、4、6、8 位十六进制色，判据即 designer-kit 的 color 编辑方式。</td></tr></tbody></table><h3 id="validation-issues" tabindex="-1">validation/issues <a class="header-anchor" href="#validation-issues" aria-label="Permalink to “validation/issues”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>ExtensionIssueCode</code></td><td>类型</td><td>扩展自己的问题码：扩展 id 的末段加点开头，如 seal.noImage；没有登记严重程度，缺省按 error。</td></tr><tr><td><code>IssueParams</code></td><td>类型</td><td>问题参数，供各语言文案插值。</td></tr><tr><td><code>VALIDATION_ISSUE_SEVERITIES</code></td><td>常量</td><td>全部问题码及其固定的严重程度：不带前缀的是 @xihan-ui/designer-kit/schema 的通用问题码，带前缀的是打印专属的问题码。</td></tr><tr><td><code>ValidationIssue</code></td><td>类型</td><td>校验问题：@xihan-ui/designer-kit/schema 的 SchemaIssue，严重程度总是给出。</td></tr><tr><td><code>ValidationIssueCode</code></td><td>类型</td><td>问题码。</td></tr><tr><td><code>ValidationReport</code></td><td>接口</td><td>校验报告。</td></tr></tbody></table><h3 id="validation-validate" tabindex="-1">validation/validate <a class="header-anchor" href="#validation-validate" aria-label="Permalink to “validation/validate”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>validateDocument</code></td><td>函数</td><td>校验模板文档：先检查 JSON 纯度，再按 schema、属性描述与元素专属规则逐层校验。</td></tr><tr><td><code>ValidateDocumentOptions</code></td><td>接口</td><td>校验选项。</td></tr></tbody></table>`,59)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};